void rotate_left(int a[], int n) {
    if (n <= 1) return;
    int first = a[0];
    for (int i = 0; i < n - 1; i++) {
        a[i] = a[i + 1];
    }
    a[n - 1] = first;
}

void rotate_left(int a[], int n) {
    if (n <= 1) return;
    int first = a[0];
    int i = 0;
    while (i < n - 1) {
        a[i] = a[i + 1];
        i++;
    }
    a[n - 1] = first;
}

void rotate_left(int a[], int n) {
    if (n <= 1) return;
    int saved = a[0];
    int i;
    for (i = 1; i < n; i++) {
        a[i - 1] = a[i];
    }
    a[n - 1] = saved;
}
